            <div class="etxt-history-group" role="group" aria-label="History & Search">
              <button type="button" class="etxt-tool-icon-btn" id="etxt-find-replace" title="Find in Document (Ctrl+F)" aria-label="Find in Document">${lt.find}</button>
              <button type="button" class="etxt-tool-icon-btn" id="etxt-undo" title="Undo (Ctrl+Z)" aria-label="Undo" ${G.length?"":"disabled"}>${lt.undo}</button>
              <button type="button" class="etxt-tool-icon-btn" id="etxt-redo" title="Redo (Ctrl+Y)" aria-label="Redo" ${q.length?"":"disabled"}>${lt.redo}</button>
            </div>

